<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\ScoringBackupService;
Auth::requireAdmin();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed.');}if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Your session expired. Please go back and try again.');}$eventIds=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['event_ids']??[($_POST['event_id']??0)])),static fn(int $id):bool=>$id>0)));if(!$eventIds){http_response_code(400);exit('Select at least one event.');}$pdo=Database::connection();$placeholders=implode(',',array_fill(0,count($eventIds),'?'));$stmt=$pdo->prepare("SELECT id,name,status FROM bdc_events WHERE id IN ($placeholders) ORDER BY id");$stmt->execute($eventIds);$events=$stmt->fetchAll();if(count($events)!==count($eventIds)){http_response_code(404);exit('One or more selected events were not found.');}foreach($events as $event){if((string)$event['status']!=='completed'){http_response_code(409);exit('Only completed events can be archived. Mark every selected event Completed first.');}}$userId=(int)(Auth::user()['id']??0);ScoringBackupService::ensure($pdo);$archive=$pdo->prepare('INSERT INTO bdc_scoring_archived_events(event_id,archived_by) VALUES(:event,:user) ON DUPLICATE KEY UPDATE archived_by=VALUES(archived_by),archived_at=NOW()');$pdo->beginTransaction();try{foreach($eventIds as $eventId){ScoringBackupService::consolidateEventForArchive($pdo,$eventId,false,$userId);$archive->execute(['event'=>$eventId,'user'=>$userId?:null]);}$pdo->commit();}catch(Throwable $error){if($pdo->inTransaction())$pdo->rollBack();throw $error;}if((string)($_POST['return_to']??'')==='dashboard'){header('Location: '.url('admin/?archived='.count($eventIds).'#archive-events'));exit;}header('Location: '.url('admin/scoring/?mode='.(string)($_POST['mode']??'manual').'&archived='.count($eventIds)));exit;
